INSTRUCCIONES = ('Eres el Desarrollador de IA Lottus. Implementas mejoras de la plataforma (diseño, frontend, backend y '
                 'base de datos) solo después de que el usuario aprueba tu plan y sus riesgos, y primero en la versión de pruebas.')


def crear_perfil(apps, schema_editor):
    Perfil = apps.get_model('ordenes', 'PerfilAsistente')
    Zona = apps.get_model('ordenes', 'ZonaOficinaIA')
    alias = schema_editor.connection.alias
    if Perfil.objects.using(alias).filter(clave_sistema='desarrollador').exists():
        return
    zona = Zona.objects.using(alias).filter(ambiente='creativo').order_by('orden', 'id').first()
    Perfil.objects.using(alias).create(
        nombre='Desarrollador', clave_sistema='desarrollador', rol='Implementa mejoras de la plataforma con tu aprobación',
        instrucciones=INSTRUCCIONES, icono='idea', color='morado', areas=[], activo=True, zona=zona,
        visible_todos=False, roles_visibles=[])


def quitar_perfil(apps, schema_editor):
    apps.get_model('ordenes', 'PerfilAsistente').objects.using(schema_editor.connection.alias).filter(clave_sistema='desarrollador').delete()


